  1→package jlsm.cache;
  2→
  3→import jlsm.core.cache.BlockCache;
  4→
  5→import java.lang.foreign.MemorySegment;
  6→import java.util.LinkedHashMap;
  7→import java.util.Map;
  8→import java.util.Objects;
  9→import java.util.Optional;
 10→import java.util.concurrent.locks.ReentrantLock;
 11→
 12→/**
 13→ * An LRU block cache backed by a {@link LinkedHashMap} with access-order eviction.
 14→ *
 15→ * <p>
 16→ * All operations are serialised through a single {@link ReentrantLock}. A {@code ReadWriteLock}
 17→ * cannot be used here because {@link LinkedHashMap#get} with {@code accessOrder=true} modifies
 18→ * internal ordering and is therefore a write-equivalent operation.
 19→ *
 20→ * <p>
 21→ * Obtain instances via {@link #builder()}.
 22→ */
 23→public final class LruBlockCache implements BlockCache {
 24→
 25→    private record CacheKey(long sstableId, long blockOffset) {
 26→    }
 27→
 28→    private final long capacity;
 29→    private final ReentrantLock lock;
 30→    private final LinkedHashMap<CacheKey, MemorySegment> map;
 31→
 32→    private LruBlockCache(Builder builder) {
 33→        assert builder.capacity > 0 : "capacity must be positive";
 34→        this.capacity = builder.capacity;
 35→        this.lock = new ReentrantLock();
 36→        final long cap = this.capacity;
 37→        this.map = new LinkedHashMap<>(16, 0.75f, true) {
 38→            @Override
 39→            protected boolean removeEldestEntry(Map.Entry<CacheKey, MemorySegment> eldest) {
 40→                return size() > cap;
 41→            }
 42→        };
 43→    }
 44→
 45→    @Override
 46→    public Optional<MemorySegment> get(long sstableId, long blockOffset) {
 47→        if (blockOffset < 0) {
 48→            throw new IllegalArgumentException(
 49→                    "blockOffset must be non-negative, got: " + blockOffset);
 50→        }
 51→        lock.lock();
 52→        try {
 53→            return Optional.ofNullable(map.get(new CacheKey(sstableId, blockOffset)));
 54→        } finally {
 55→            lock.unlock();
 56→        }
 57→    }
 58→
 59→    @Override
 60→    public void put(long sstableId, long blockOffset, MemorySegment block) {
 61→        if (blockOffset < 0) {
 62→            throw new IllegalArgumentException(
 63→                    "blockOffset must be non-negative, got: " + blockOffset);
 64→        }
 65→        Objects.requireNonNull(block, "block must not be null");
 66→        lock.lock();
 67→        try {
 68→            map.put(new CacheKey(sstableId, blockOffset), block);
 69→        } finally {
 70→            lock.unlock();
 71→        }
 72→    }
 73→
 74→    @Override
 75→    public void evict(long sstableId) {
 76→        lock.lock();
 77→        try {
 78→            map.keySet().removeIf(k -> k.sstableId() == sstableId);
 79→        } finally {
 80→            lock.unlock();
 81→        }
 82→    }
 83→
 84→    @Override
 85→    public long size() {
 86→        lock.lock();
 87→        try {
 88→            return map.size();
 89→        } finally {
 90→            lock.unlock();
 91→        }
 92→    }
 93→
 94→    @Override
 95→    public long capacity() {
 96→        return capacity;
 97→    }
 98→
 99→    @Override
100→    public void close() {
101→        lock.lock();
102→        try {
103→            map.clear();
104→        } finally {
105→            lock.unlock();
106→        }
107→    }
108→
109→    public static Builder builder() {
110→        return new Builder();
111→    }
112→
113→    public static final class Builder {
114→        private long capacity = -1;
115→
116→        private Builder() {
117→        }
118→
119→        public Builder capacity(long capacity) {
120→            this.capacity = capacity;
121→            return this;
122→        }
123→
124→        public LruBlockCache build() {
125→            if (capacity <= 0) {
126→                throw new IllegalArgumentException("capacity must be positive, got: " + capacity);
127→            }
128→            return new LruBlockCache(this);
129→        }
130→    }
131→}
